INSERT INTO states (name,type,capital,region,description,image_url,best_time,language,famous_for,destinations_count) VALUES
('Andhra Pradesh','state','Amaravati','South','Coastal state with ancient temples, beaches, and the scenic Araku Valley.','https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Tirumala_090615.jpg/1200px-Tirumala_090615.jpg','October–March','Telugu','Tirupati, Araku Valley, Lepakshi','8'),
('Arunachal Pradesh','state','Itanagar','Northeast','The land of the dawn-lit mountains bordering Tibet, Myanmar and Bhutan with pristine valleys.','https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/TawangMonastery-ArunachalPradesh-1.jpg/1200px-TawangMonastery-ArunachalPradesh-1.jpg','October–April','English, Hindi','Tawang, Ziro Valley, Sela Pass','6'),
('Assam','state','Dispur','Northeast','Gateway to Northeast India, home to one-horned rhinos and the world''s largest river island.','https://upload.wikimedia.org/wikipedia/commons/f/fe/Beauty_of_Kaziranga_National_Park.jpg','November–April','Assamese','Kaziranga, Majuli Island, Kamakhya Temple','9'),
('Bihar','state','Patna','East','Cradle of civilization — birthplace of Buddhism and Jainism, abode of ancient empires.','https://upload.wikimedia.org/wikipedia/commons/e/e6/Mahabodhi_temple_complex%2C_Bodhgaya_27.jpg','October–March','Hindi','Bodh Gaya, Nalanda, Rajgir','7'),
('Chhattisgarh','state','Raipur','Central','Heart of India with dense forests, tribal culture, cascading waterfalls and ancient temples.','https://upload.wikimedia.org/wikipedia/commons/b/b1/Bhoramdeo_Temple%2C_Kawardha.jpg','October–February','Hindi','Chitrakote Falls, Bastar, Sirpur','6'),
('Goa','state','Panaji','West','India''s smallest state — a paradise of golden beaches, Portuguese churches and vibrant nightlife.','https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/BeachFun.jpg/1200px-BeachFun.jpg','November–February','Konkani','Anjuna Beach, Old Goa, Dudhsagar Falls','10'),
('Gujarat','state','Gandhinagar','West','Land of Gandhi and iconic Rann of Kutch — vibrant textiles, lion sanctuary and salt deserts.','https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Rani_ki_vav_02.jpg/1200px-Rani_ki_vav_02.jpg','October–March','Gujarati','Gir Forest, Rann of Kutch, Dwarka','10'),
('Haryana','state','Chandigarh','North','The granary of India with Kurukshetra, the land of Mahabharata and modern planned cities.','https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/Cyber_City_View.jpg/1200px-Cyber_City_View.jpg','October–March','Hindi','Kurukshetra, Sultanpur Bird Sanctuary','5'),
('Himachal Pradesh','state','Shimla','North','The land of gods — snow-capped peaks, apple orchards, ancient temples and adventure sports.','https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Kullu_Valley_near_Manali%2C_Himachal_Pradesh%2C_India.jpg/1200px-Kullu_Valley_near_Manali%2C_Himachal_Pradesh%2C_India.jpg','March–June, Sep–Dec','Hindi','Manali, Shimla, Spiti Valley, Dharamsala','11'),
('Jharkhand','state','Ranchi','East','The "Land of Forests" — rich in mineral wealth, tribal culture, stunning waterfalls.','https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/Views_of_Shikharji_on_way_to_Anantnatha_Tonk_3.jpg/1200px-Views_of_Shikharji_on_way_to_Anantnatha_Tonk_3.jpg','October–March','Hindi','Betla, Hundru Falls, Deoghar','6'),
('Karnataka','state','Bengaluru','South','Where ancient Hoysala temples, Mysore palaces, tiger reserves and tech hubs coexist.','https://upload.wikimedia.org/wikipedia/commons/4/4b/Hampi_virupaksha_temple.jpg','October–February','Kannada','Mysore, Hampi, Coorg, Gokarna','13'),
('Kerala','state','Thiruvananthapuram','South','God''s Own Country — serene backwaters, elephant processions, Ayurveda and spice gardens.','https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Boathouse_%287063399547%29.jpg/1200px-Boathouse_%287063399547%29.jpg','September–March','Malayalam','Munnar, Alleppey, Kovalam, Wayanad','12'),
('Madhya Pradesh','state','Bhopal','Central','The heart of India with Khajuraho temples, tiger reserves, Sanchi stupa and Orchha forts.','https://upload.wikimedia.org/wikipedia/commons/6/68/India-5749_-_Visvanatha_Temple_-_Flickr_-_archer10_%28Dennis%29.jpg','October–March','Hindi','Khajuraho, Kanha, Bandhavgarh, Gwalior','12'),
('Maharashtra','state','Mumbai','West','India''s financial capital — home to Bollywood, Ajanta-Ellora caves, hill stations and beaches.','https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Cave_26%2C_Ajanta.jpg/1200px-Cave_26%2C_Ajanta.jpg','November–February','Marathi','Mumbai, Ajanta Ellora, Lonavala, Pune','14'),
('Manipur','state','Imphal','Northeast','The jewel of India — birthplace of polo, Loktak Lake, Sangai deer and classical dance forms.','https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Breathtaking_beauty_of_Dzukou_Valley_in_Manipur-Nagaland_border_%28edit%29.jpg/1200px-Breathtaking_beauty_of_Dzukou_Valley_in_Manipur-Nagaland_border_%28edit%29.jpg','October–March','Meitei','Loktak Lake, Keibul Lamjao, Imphal','5'),
('Meghalaya','state','Shillong','Northeast','Abode of clouds — wettest place on earth, living root bridges and stunning waterfalls.','https://upload.wikimedia.org/wikipedia/commons/thumb/5/55/Dawki_River%2C_Meghalaya%2C_India.jpg/1200px-Dawki_River%2C_Meghalaya%2C_India.jpg','October–June','Khasi','Cherrapunji, Dawki, Mawlynnong','7'),
('Mizoram','state','Aizawl','Northeast','Land of the highlanders — serene bamboo forests, blue lakes and rich Mizo culture.','https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/Embossed_Figures_Kawtchhuah_Ropui_Vangchhia_Mapuia_Hnamte_%281%29.JPG/1200px-Embossed_Figures_Kawtchhuah_Ropui_Vangchhia_Mapuia_Hnamte_%281%29.JPG','October–March','Mizo','Aizawl, Phawngpui, Palak Lake','4'),
('Nagaland','state','Kohima','Northeast','Land of festivals — famous for the Hornbill Festival, tribal heritage and Dzükou Valley.','https://upload.wikimedia.org/wikipedia/commons/c/cb/Kapamodzu.jpg','October–May','English','Kohima, Dzükou Valley, Hornbill Festival','5'),
('Odisha','state','Bhubaneswar','East','Temple city of India — Jagannath Puri, Sun Temple Konark, ancient caves and marine wildlife.','https://upload.wikimedia.org/wikipedia/commons/0/0d/Brahmeswar_Temple%2C_Bhubaneswar.JPG','October–March','Odia','Puri, Konark, Bhubaneswar, Chilika Lake','10'),
('Punjab','state','Chandigarh','North','The land of five rivers — Golden Temple, bhangra, butter chicken and Wagah Border.','https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Golden_Temple%2C_Amritsar%2C_Punjab_UNAG.jpg/1200px-Golden_Temple%2C_Amritsar%2C_Punjab_UNAG.jpg','October–March','Punjabi','Golden Temple, Wagah Border, Anandpur Sahib','7'),
('Rajasthan','state','Jaipur','North','The Land of Kings — majestic forts, palatial havelis, camel safaris and vibrant festivals.','https://upload.wikimedia.org/wikipedia/commons/0/09/Thar_Khuri.jpg','October–March','Hindi','Jaipur, Jodhpur, Udaipur, Jaisalmer','15'),
('Sikkim','state','Gangtok','Northeast','Himalayan heaven — Kanchenjunga views, Buddhist monasteries, rhododendron forests and Tsomgo lake.','https://upload.wikimedia.org/wikipedia/commons/f/f9/Buddha_statue_at_Buddha_Park_of_Ravangla%2C_Sikkim%2C_India_%281%29.jpg','March–May, Oct–Dec','Nepali','Gangtok, Pelling, Yuksom, Tsomgo Lake','8'),
('Tamil Nadu','state','Chennai','South','Classical land of Dravidian temples, Carnatic music, silk sarees and Marina Beach.','https://upload.wikimedia.org/wikipedia/commons/f/f2/Mamallapuram_view.jpg','November–February','Tamil','Madurai, Ooty, Mahabalipuram, Rameswaram','14'),
('Telangana','state','Hyderabad','South','City of pearls — Charminar, biryani, Golconda Fort and Hussain Sagar Lake.','https://upload.wikimedia.org/wikipedia/commons/f/f7/A_typical_charminar_evening.jpg','October–February','Telugu','Hyderabad, Warangal, Nagarjuna Sagar','7'),
('Tripura','state','Agartala','Northeast','Seven Sister state with ancient Ujjayanta Palace, Neermahal water palace and lush forests.','https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/Tripura_State_Museum_Agartala_Tripura_India.jpg/1200px-Tripura_State_Museum_Agartala_Tripura_India.jpg','October–March','Bengali','Agartala, Neermahal, Unakoti','4'),
('Uttar Pradesh','state','Lucknow','North','The spiritual heartland — Taj Mahal, Varanasi ghats, Ayodhya, Mathura and Agra Fort.','https://upload.wikimedia.org/wikipedia/commons/1/1d/Taj_Mahal_%28Edited%29.jpeg','October–March','Hindi','Agra, Varanasi, Lucknow, Mathura, Ayodhya','16'),
('Uttarakhand','state','Dehradun','North','Devbhoomi — the land of gods with Char Dham, Jim Corbett, Valley of Flowers and Rishikesh.','https://upload.wikimedia.org/wikipedia/commons/thumb/5/56/Kedarnath_Temple_in_Rainy_season.jpg/1200px-Kedarnath_Temple_in_Rainy_season.jpg','March–June, Sep–Nov','Hindi','Haridwar, Rishikesh, Mussoorie, Dehradun','12'),
('West Bengal','state','Kolkata','East','Cultural capital of India — Victoria Memorial, Sundarbans tiger reserve, Darjeeling tea gardens.','https://upload.wikimedia.org/wikipedia/commons/3/32/Dakhineshwar_Temple_beside_the_Hoogly%2C_West_Bengal.JPG','October–March','Bengali','Kolkata, Darjeeling, Sundarbans, Murshidabad','11');
INSERT INTO states (name,type,capital,region,description,image_url,best_time,language,famous_for,destinations_count) VALUES
('Andaman and Nicobar Islands','union_territory','Port Blair','South','Emerald island chain with crystal-clear waters, coral reefs and pristine beaches.','https://upload.wikimedia.org/wikipedia/commons/2/2f/The_Coral_Reef_at_the_Andaman_Islands.jpg','October–May','Hindi, Bengali','Radhanagar Beach, Cellular Jail, Havelock Island','8'),
('Chandigarh','union_territory','Chandigarh','North','India''s first planned city designed by Le Corbusier — clean, green and modern.','https://upload.wikimedia.org/wikipedia/commons/7/76/Open_Hand_monument%2C_Chandigarh.jpg','October–March','Hindi, Punjabi','Rock Garden, Sukhna Lake, Rose Garden','4'),
('Dadra and Nagar Haveli and Daman and Diu','union_territory','Daman','West','Blend of Portuguese heritage and Gujarat culture — beaches, forts and tribal life.','https://upload.wikimedia.org/wikipedia/commons/5/5f/Vanganga_Garden%2C_Silvassa_%2832345632184%29.jpg','November–March','Gujarati, Hindi','Daman Fort, Jampore Beach, Silvassa','4'),
('Delhi','union_territory','New Delhi','North','The capital that spans 5,000 years of history — Mughal marvels and modern India combined.','https://upload.wikimedia.org/wikipedia/commons/4/40/Jama_Masjid_2011.jpg','October–March','Hindi','India Gate, Red Fort, Qutub Minar, Lotus Temple','12'),
('Jammu and Kashmir','union_territory','Srinagar','North','Heaven on Earth — Dal Lake houseboats, snow-capped Gulmarg and ancient Vaishno Devi temple.','https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/Pahalgam_Valley.jpg/1200px-Pahalgam_Valley.jpg','April–October','Kashmiri, Urdu','Dal Lake, Gulmarg, Pahalgam, Vaishno Devi','10'),
('Ladakh','union_territory','Leh','North','The last Shangri-La — moonscapes, ancient monasteries, Pangong Lake and Khardung La pass.','https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Pangong_Tso_2.jpg/1200px-Pangong_Tso_2.jpg','June–September','Ladakhi, Hindi','Pangong Lake, Nubra Valley, Leh Palace, Tso Moriri','9'),
('Lakshadweep','union_territory','Kavaratti','South','India''s coral island paradise — untouched lagoons, white sandy beaches and marine life.','https://upload.wikimedia.org/wikipedia/commons/7/72/A_beach_side_resort_at_Kadmat_Island%2C_Lakshadweep.jpg','October–May','Malayalam','Agatti Island, Bangaram, Minicoy','4'),
('Puducherry','union_territory','Puducherry','South','The French Riviera of the East — colonial boulevards, ashrams, seafood and beach cafes.','https://commons.wikimedia.org/wiki/Special:FilePath/Pondicherry_shoreline.jpg?width=1200','October–February','Tamil, French','French Quarter, Auroville, Paradise Beach','6');
